import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            A1 = int(next(iterator))
            D = int(next(iterator))
            L = int(next(iterator))
            R = int(next(iterator))
        except StopIteration:
            break

        count = R - L + 1

        if D == 0:
            val = A1
            while val > 9:
                s = 0
                temp = val
                while temp:
                    s += temp % 10
                    temp //= 10
                val = s

            total = val * count
            results.append(str(total))
            continue

        def get_f(x):
            if x < 10:
                return x
            if x % 9 == 0:
                return 9
            return x % 9

        start_val = A1 + (L - 1) * D

        cycle_len = 9 // gcd(D, 9)

        full_cycles = count // cycle_len
        remainder = count % cycle_len

        current = start_val
        cycle_sum = 0

        for _ in range(cycle_len):
            cycle_sum += get_f(current)
            current += D

        total = full_cycles * cycle_sum

        current = start_val
        for _ in range(remainder):
            total += get_f(current)
            current += D

        results.append(str(total))

    sys.stdout.write('\n'.join(results) + '\n')

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

if __name__ == "__main__":
    main()
